arguments.content:
terraform {
  required_version = ">= 1.6.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0.0"
    }
  }
}

variable "resource_prefix" {
  type = string
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "aws_endpoint_url" {
  type    = string
  default = "http://aws:4566"
}

variable "db_name" {
  type = string
}

variable "db_username" {
  type = string
}

variable "db_password" {
  type      = string
  sensitive = true
}

variable "api_image" {
  type = string
}

variable "projector_image" {
  type = string
}

variable "relay_image" {
  type = string
}

variable "archiver_image" {
  type = string
}

variable "api_image_id" {
  type    = string
  default = ""
}

variable "projector_image_id" {
  type    = string
  default = ""
}

variable "relay_image_id" {
  type    = string
  default = ""
}

variable "archiver_image_id" {
  type    = string
  default = ""
}

provider "aws" {
  region                      = var.region
  access_key                  = "test"
  secret_key                  = "test"
  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_requesting_account_id  = true
  skip_region_validation      = true
  s3_use_path_style           = true

  endpoints {
    acm              = var.aws_endpoint_url
    cloudwatch       = var.aws_endpoint_url
    cloudwatchlogs   = var.aws_endpoint_url
    cognitoidp       = var.aws_endpoint_url
    dynamodb         = var.aws_endpoint_url
    ec2              = var.aws_endpoint_url
    ecs              = var.aws_endpoint_url
    elasticache      = var.aws_endpoint_url
    elbv2            = var.aws_endpoint_url
    events           = var.aws_endpoint_url
    iam              = var.aws_endpoint_url
    kms              = var.aws_endpoint_url
    lambda           = var.aws_endpoint_url
    rds              = var.aws_endpoint_url
    s3               = var.aws_endpoint_url
    scheduler        = var.aws_endpoint_url
    secretsmanager   = var.aws_endpoint_url
    sns              = var.aws_endpoint_url
    sqs              = var.aws_endpoint_url
    ssm              = var.aws_endpoint_url
    sts              = var.aws_endpoint_url
    resourcegroupstaggingapi = var.aws_endpoint_url
  }

  default_tags {
    tags = {
      ClearLedgerDeployment = var.resource_prefix
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  p          = var.resource_prefix
  account_id = data.aws_caller_identity.current.account_id
  azs        = ["${var.region}a", "${var.region}b"]
  tags       = { ClearLedgerDeployment = var.resource_prefix }

  # Endpoint reachable from inside containers (ECS tasks and Lambda functions).
  container_aws_endpoint = var.aws_endpoint_url

  log_group_names = {
    api       = "/clearledger/${var.resource_prefix}/api"
    projector = "/clearledger/${var.resource_prefix}/projector"
    relay     = "/clearledger/${var.resource_prefix}/outbox-relay"
    archiver  = "/clearledger/${var.resource_prefix}/audit-archiver"
  }

  database_url = "postgres://${var.db_username}:${var.db_password}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${var.db_name}"
  valkey_host  = aws_elasticache_replication_group.cache.primary_endpoint_address
  valkey_port  = aws_elasticache_replication_group.cache.port
  valkey_url   = "redis://${local.valkey_host}:${local.valkey_port}"

  issuer_url     = "${var.aws_endpoint_url}/${aws_cognito_user_pool.main.id}"
  jwks_url       = "${var.aws_endpoint_url}/${aws_cognito_user_pool.main.id}/.well-known/jwks.json"
  token_endpoint = "${var.aws_endpoint_url}/cognito-idp/oauth2/token"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.42.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(local.tags, { Name = "${local.p}-vpc" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true
  tags                    = merge(local.tags, { Name = "${local.p}-public-${local.azs[count.index]}", Tier = "public" })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  tags                    = merge(local.tags, { Name = "${local.p}-private-${local.azs[count.index]}", Tier = "private" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.p}-igw" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.p}-public-rt" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.p}-private-rt" })
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups (rules declared inline so Terraform owns the full rule set
# and revokes any out-of-band additions on every apply).
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name                   = "${local.p}-alb"
  description            = "ClearLedger ALB - HTTP from internet, 8080 to ECS only"
  vpc_id                 = aws_vpc.main.id
  revoke_rules_on_delete = true

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Forward to API tasks"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, { Name = "${local.p}-alb" })
}

resource "aws_security_group" "ecs" {
  name                   = "${local.p}-ecs"
  description            = "ClearLedger API tasks - 8080 from ALB only"
  vpc_id                 = aws_vpc.main.id
  revoke_rules_on_delete = true

  ingress {
    description     = "API traffic from ALB"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound to AWS control plane and data stores"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${local.p}-ecs" })
}

resource "aws_security_group" "rds" {
  name                   = "${local.p}-rds"
  description            = "ClearLedger PostgreSQL - 5432 from ECS and VPC workers"
  vpc_id                 = aws_vpc.main.id
  revoke_rules_on_delete = true

  ingress {
    description     = "PostgreSQL from API tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  ingress {
    description = "PostgreSQL from VPC workers"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.p}-rds" })
}

resource "aws_security_group" "valkey" {
  name                   = "${local.p}-valkey"
  description            = "ClearLedger Valkey - 6379 from ECS and VPC workers"
  vpc_id                 = aws_vpc.main.id
  revoke_rules_on_delete = true

  ingress {
    description     = "Valkey from API tasks"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  ingress {
    description = "Valkey from VPC workers"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.p}-valkey" })
}

locals {
  role_arns = {
    ecs_execution = aws_iam_role.ecs_execution.arn
    ecs_task      = aws_iam_role.ecs_task.arn
    projector     = aws_iam_role.projector.arn
    relay         = aws_iam_role.relay.arn
    archiver      = aws_iam_role.archiver.arn
    scheduler     = aws_iam_role.scheduler.arn
  }

  kms_usage = {
    database   = ["relay", "archiver"]
    messaging  = ["ecs_task", "projector", "relay"]
    projection = ["ecs_task", "projector"]
    audit      = ["archiver"]
  }

  kms_descriptions = {
    database   = "ClearLedger RDS PostgreSQL encryption"
    messaging  = "ClearLedger SQS queue and DLQ encryption"
    projection = "ClearLedger DynamoDB projection encryption"
    audit      = "ClearLedger S3 audit archive encryption"
  }
}

resource "aws_kms_key" "key" {
  for_each                = local.kms_usage
  description             = "${local.p} ${local.kms_descriptions[each.key]}"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  is_enabled              = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.p}-${each.key}-key-policy"
    Statement = [
      {
        Sid       = "EnableRootAccountAdministration"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowAuthorizedWorkloadCryptoUsage"
        Effect    = "Allow"
        Principal = { AWS = [for r in each.value : local.role_arns[r]] }
        Action    = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource  = "*"
      },
      {
        Sid       = "DenyWorkloadKeyDisableOrDeletion"
        Effect    = "Deny"
        Principal = { AWS = values(local.role_arns) }
        Action    = ["kms:DisableKey", "kms:ScheduleKeyDeletion"]
        Resource  = "*"
      },
      {
        Sid       = "DenyUnauthorizedWorkloadCryptoUsage"
        Effect    = "Deny"
        Principal = { AWS = [for r, arn in local.role_arns : arn if !contains(each.value, r)] }
        Action    = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource  = "*"
      }
    ]
  })

  tags = merge(local.tags, {
    Name                = "${local.p}-${each.key}"
    ClearLedgerKeyUsage = each.key
  })
}

resource "aws_kms_alias" "key" {
  for_each      = local.kms_usage
  name          = "alias/${local.p}-${each.key}"
  target_key_id = aws_kms_key.key[each.key].key_id
}

locals {
  queue_arn  = aws_sqs_queue.main.arn
  dlq_arn    = aws_sqs_queue.dlq.arn
  table_arn  = aws_dynamodb_table.projections.arn
  gsi_arn    = "${aws_dynamodb_table.projections.arn}/index/AccountIndex"
  bucket_arn = aws_s3_bucket.audit.arn

  kms_arns = { for k, v in aws_kms_key.key : k => v.arn }
  all_kms  = values(local.kms_arns)

  log_arns = {
    for k, name in local.log_group_names : k => [
      "arn:aws:logs:${var.region}:${local.account_id}:log-group:${name}",
      "arn:aws:logs:${var.region}:${local.account_id}:log-group:${name}:*",
    ]
  }

  log_write_actions = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
  log_deny_actions  = ["logs:CreateLogStream", "logs:PutLogEvents"]
  sqs_all_actions   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
  ddb_all_actions   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
  s3_all_actions    = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
  s3_resources      = [local.bucket_arn, "${local.bucket_arn}/*"]

  kms_guardrail = {
    Sid      = "DenyKmsKeyDisableOrDeletion"
    Effect   = "Deny"
    Action   = ["kms:DisableKey", "kms:ScheduleKeyDeletion"]
    Resource = local.all_kms
  }

  other_logs = {
    for k in keys(local.log_group_names) : k => flatten([for o, arns in local.log_arns : arns if o != k])
  }

  trust = {
    ecs       = "ecs-tasks.amazonaws.com"
    lambda    = "lambda.amazonaws.com"
    scheduler = "scheduler.amazonaws.com"
  }
}

data "aws_iam_policy_document" "trust" {
  for_each = local.trust
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = [each.value]
    }
  }
}

# ---------------------------------------------------------------------------
# Roles
# ---------------------------------------------------------------------------

resource "aws_iam_role" "ecs_execution" {
  name               = "${local.p}-ecs-execution"
  assume_role_policy = data.aws_iam_policy_document.trust["ecs"].json
  tags               = merge(local.tags, { ClearLedgerRole = "ecs_execution" })
}

resource "aws_iam_role" "ecs_task" {
  name               = "${local.p}-ecs-task"
  assume_role_policy = data.aws_iam_policy_document.trust["ecs"].json
  tags               = merge(local.tags, { ClearLedgerRole = "ecs_task" })
}

resource "aws_iam_role" "projector" {
  name               = "${local.p}-projector"
  assume_role_policy = data.aws_iam_policy_document.trust["lambda"].json
  tags               = merge(local.tags, { ClearLedgerRole = "projector" })
}

resource "aws_iam_role" "relay" {
  name               = "${local.p}-relay"
  assume_role_policy = data.aws_iam_policy_document.trust["lambda"].json
  tags               = merge(local.tags, { ClearLedgerRole = "relay" })
}

resource "aws_iam_role" "archiver" {
  name               = "${local.p}-archiver"
  assume_role_policy = data.aws_iam_policy_document.trust["lambda"].json
  tags               = merge(local.tags, { ClearLedgerRole = "archiver" })
}

resource "aws_iam_role" "scheduler" {
  name               = "${local.p}-scheduler"
  assume_role_policy = data.aws_iam_policy_document.trust["scheduler"].json
  tags               = merge(local.tags, { ClearLedgerRole = "scheduler" })
}

# ---------------------------------------------------------------------------
# Inline least-privilege policies
# ---------------------------------------------------------------------------

resource "aws_iam_role_policy" "ecs_execution" {
  name = "${local.p}-ecs-execution-policy"
  role = aws_iam_role.ecs_execution.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      { Sid = "ApiLogWrite", Effect = "Allow", Action = local.log_write_actions, Resource = local.log_arns.api },
      local.kms_guardrail,
      { Sid = "DenySqs", Effect = "Deny", Action = local.sqs_all_actions, Resource = [local.queue_arn, local.dlq_arn] },
      { Sid = "DenyDynamoDb", Effect = "Deny", Action = local.ddb_all_actions, Resource = [local.table_arn, local.gsi_arn] },
      { Sid = "DenyS3", Effect = "Deny", Action = local.s3_all_actions, Resource = local.s3_resources },
      { Sid = "DenyKmsCrypto", Effect = "Deny", Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = local.all_kms },
      { Sid = "DenyOtherLogGroups", Effect = "Deny", Action = local.log_deny_actions, Resource = local.other_logs.api },
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task" {
  name = "${local.p}-ecs-task-policy"
  role = aws_iam_role.ecs_task.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      { Sid = "PublishMainQueue", Effect = "Allow", Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = local.queue_arn },
      { Sid = "ReadProjections", Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"], Resource = [local.table_arn, local.gsi_arn] },
      { Sid = "KmsCrypto", Effect = "Allow", Action = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"], Resource = [local.kms_arns.messaging, local.kms_arns.projection] },
      { Sid = "ApiLogWrite", Effect = "Allow", Action = local.log_write_actions, Resource = local.log_arns.api },
      local.kms_guardrail,
      { Sid = "DenyConsumeMainQueue", Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = local.queue_arn },
      { Sid = "DenyDlq", Effect = "Deny", Action = local.sqs_all_actions, Resource = local.dlq_arn },
      { Sid = "DenyDynamoDbMutation", Effect = "Deny", Action = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = [local.table_arn, local.gsi_arn] },
      { Sid = "DenyS3", Effect = "Deny", Action = local.s3_all_actions, Resource = local.s3_resources },
      { Sid = "DenyKmsCrypto", Effect = "Deny", Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = [local.kms_arns.database, local.kms_arns.audit] },
      { Sid = "DenyOtherLogGroups", Effect = "Deny", Action = local.log_deny_actions, Resource = local.other_logs.api },
    ]
  })
}

resource "aws_iam_role_policy" "projector" {
  name = "${local.p}-projector-policy"
  role = aws_iam_role.projector.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      { Sid = "ConsumeMainQueue", Effect = "Allow", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"], Resource = local.queue_arn },
      { Sid = "ForwardToDlq", Effect = "Allow", Action = ["sqs:SendMessage"], Resource = local.dlq_arn },
      { Sid = "UpsertProjections", Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"], Resource = [local.table_arn, local.gsi_arn] },
      { Sid = "KmsCrypto", Effect = "Allow", Action = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"], Resource = [local.kms_arns.messaging, local.kms_arns.projection] },
      { Sid = "ProjectorLogWrite", Effect = "Allow", Action = local.log_write_actions, Resource = local.log_arns.projector },
      local.kms_guardrail,
      { Sid = "DenyPublishMainQueue", Effect = "Deny", Action = ["sqs:SendMessage"], Resource = local.queue_arn },
      { Sid = "DenyConsumeDlq", Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = local.dlq_arn },
      { Sid = "DenyDynamoDbDelete", Effect = "Deny", Action = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = [local.table_arn, local.gsi_arn] },
      { Sid = "DenyS3", Effect = "Deny", Action = local.s3_all_actions, Resource = local.s3_resources },
      { Sid = "DenyKmsCrypto", Effect = "Deny", Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = [local.kms_arns.database, local.kms_arns.audit] },
      { Sid = "DenyOtherLogGroups", Effect = "Deny", Action = local.log_deny_actions, Resource = local.other_logs.projector },
    ]
  })
}

resource "aws_iam_role_policy" "relay" {
  name = "${local.p}-relay-policy"
  role = aws_iam_role.relay.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      { Sid = "PublishMainQueue", Effect = "Allow", Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = local.queue_arn },
      { Sid = "KmsCrypto", Effect = "Allow", Action = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"], Resource = [local.kms_arns.messaging, local.kms_arns.database] },
      { Sid = "RelayLogWrite", Effect = "Allow", Action = local.log_write_actions, Resource = local.log_arns.relay },
      local.kms_guardrail,
      { Sid = "DenyConsumeMainQueue", Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = local.queue_arn },
      { Sid = "DenyDlq", Effect = "Deny", Action = local.sqs_all_actions, Resource = local.dlq_arn },
      { Sid = "DenyDynamoDb", Effect = "Deny", Action = local.ddb_all_actions, Resource = [local.table_arn, local.gsi_arn] },
      { Sid = "DenyS3", Effect = "Deny", Action = local.s3_all_actions, Resource = local.s3_resources },
      { Sid = "DenyKmsCrypto", Effect = "Deny", Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = [local.kms_arns.projection, local.kms_arns.audit] },
      { Sid = "DenyOtherLogGroups", Effect = "Deny", Action = local.log_deny_actions, Resource = local.other_logs.relay },
    ]
  })
}

resource "aws_iam_role_policy" "archiver" {
  name = "${local.p}-archiver-policy"
  role = aws_iam_role.archiver.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      { Sid = "AuditObjectAppend", Effect = "Allow", Action = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"], Resource = "${local.bucket_arn}/ledger-audit/*" },
      { Sid = "AuditBucketMetadata", Effect = "Allow", Action = ["s3:ListBucket", "s3:GetBucketLocation"], Resource = local.bucket_arn },
      { Sid = "KmsCrypto", Effect = "Allow", Action = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"], Resource = [local.kms_arns.audit, local.kms_arns.database] },
      { Sid = "ArchiverLogWrite", Effect = "Allow", Action = local.log_write_actions, Resource = local.log_arns.archiver },
      local.kms_guardrail,
      { Sid = "DenyS3Delete", Effect = "Deny", Action = ["s3:DeleteObject", "s3:DeleteObjectVersion"], Resource = local.s3_resources },
      { Sid = "DenyPutOutsideAuditPrefix", Effect = "Deny", Action = ["s3:PutObject"], NotResource = "${local.bucket_arn}/ledger-audit/*" },
      { Sid = "DenySqs", Effect = "Deny", Action = local.sqs_all_actions, Resource = [local.queue_arn, local.dlq_arn] },
      { Sid = "DenyDynamoDb", Effect = "Deny", Action = local.ddb_all_actions, Resource = [local.table_arn, local.gsi_arn] },
      { Sid = "DenyKmsCrypto", Effect = "Deny", Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = [local.kms_arns.messaging, local.kms_arns.projection] },
      { Sid = "DenyOtherLogGroups", Effect = "Deny", Action = local.log_deny_actions, Resource = local.other_logs.archiver },
    ]
  })
}

resource "aws_iam_role_policy" "scheduler" {
  name = "${local.p}-scheduler-policy"
  role = aws_iam_role.scheduler.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      { Sid = "InvokeScheduledWorkers", Effect = "Allow", Action = ["lambda:InvokeFunction"], Resource = [aws_lambda_function.relay.arn, aws_lambda_function.archiver.arn] },
      local.kms_guardrail,
      { Sid = "DenyInvokeProjector", Effect = "Deny", Action = ["lambda:InvokeFunction"], Resource = [aws_lambda_function.projector.arn] },
      { Sid = "DenySqs", Effect = "Deny", Action = local.sqs_all_actions, Resource = [local.queue_arn, local.dlq_arn] },
      { Sid = "DenyDynamoDb", Effect = "Deny", Action = local.ddb_all_actions, Resource = [local.table_arn, local.gsi_arn] },
      { Sid = "DenyS3", Effect = "Deny", Action = local.s3_all_actions, Resource = local.s3_resources },
      { Sid = "DenyKmsCrypto", Effect = "Deny", Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = local.all_kms },
      { Sid = "DenyAllLogGroups", Effect = "Deny", Action = local.log_deny_actions, Resource = flatten(values(local.log_arns)) },
    ]
  })
}

# ---------------------------------------------------------------------------
# Exclusivity: strip any out-of-band inline or attached managed policies.
# ---------------------------------------------------------------------------

locals {
  canonical_inline = {
    ecs_execution = { role = aws_iam_role.ecs_execution.name, policy = aws_iam_role_policy.ecs_execution.name }
    ecs_task      = { role = aws_iam_role.ecs_task.name, policy = aws_iam_role_policy.ecs_task.name }
    projector     = { role = aws_iam_role.projector.name, policy = aws_iam_role_policy.projector.name }
    relay         = { role = aws_iam_role.relay.name, policy = aws_iam_role_policy.relay.name }
    archiver      = { role = aws_iam_role.archiver.name, policy = aws_iam_role_policy.archiver.name }
    scheduler     = { role = aws_iam_role.scheduler.name, policy = aws_iam_role_policy.scheduler.name }
  }
}

resource "aws_iam_role_policies_exclusive" "role" {
  for_each     = local.canonical_inline
  role_name    = each.value.role
  policy_names = [each.value.policy]
}

resource "aws_iam_role_policy_attachments_exclusive" "role" {
  for_each    = local.canonical_inline
  role_name   = each.value.role
  policy_arns = []
}

# ---------------------------------------------------------------------------
# CloudWatch Log Groups
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "lg" {
  for_each          = local.log_group_names
  name              = each.value
  retention_in_days = 14
  tags              = merge(local.tags, { ClearLedgerWorkload = each.key })
}

# ---------------------------------------------------------------------------
# SQS
# ---------------------------------------------------------------------------

resource "aws_sqs_queue" "dlq" {
  name                      = "${local.p}-settlement-events-dlq"
  kms_master_key_id         = aws_kms_key.key["messaging"].arn
  message_retention_seconds = 1209600
  tags                      = local.tags
}

resource "aws_sqs_queue" "main" {
  name                       = "${local.p}-settlement-events"
  kms_master_key_id          = aws_kms_key.key["messaging"].arn
  visibility_timeout_seconds = 3
  receive_wait_time_seconds  = 2
  message_retention_seconds  = 172800
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })
  tags = local.tags
}

resource "aws_sqs_queue_policy" "main" {
  queue_url = aws_sqs_queue.main.id
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.p}-settlement-events-policy"
    Statement = [
      {
        Sid       = "AllowPublishers"
        Effect    = "Allow"
        Principal = { AWS = [aws_iam_role.ecs_task.arn, aws_iam_role.relay.arn] }
        Action    = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource  = aws_sqs_queue.main.arn
      },
      {
        Sid       = "AllowProjectorConsumer"
        Effect    = "Allow"
        Principal = { AWS = [aws_iam_role.projector.arn] }
        Action    = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"]
        Resource  = aws_sqs_queue.main.arn
      },
      {
        Sid    = "DenyNonPublisherSend"
        Effect = "Deny"
        Principal = { AWS = [
          aws_iam_role.ecs_execution.arn, aws_iam_role.projector.arn,
          aws_iam_role.archiver.arn, aws_iam_role.scheduler.arn,
        ] }
        Action   = ["sqs:SendMessage"]
        Resource = aws_sqs_queue.main.arn
      },
      {
        Sid    = "DenyNonConsumerReceive"
        Effect = "Deny"
        Principal = { AWS = [
          aws_iam_role.ecs_execution.arn, aws_iam_role.ecs_task.arn, aws_iam_role.relay.arn,
          aws_iam_role.archiver.arn, aws_iam_role.scheduler.arn,
        ] }
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = aws_sqs_queue.main.arn
      },
    ]
  })
}

resource "aws_sqs_queue_policy" "dlq" {
  queue_url = aws_sqs_queue.dlq.id
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.p}-settlement-events-dlq-policy"
    Statement = [
      {
        Sid       = "AllowProjectorDeadLetter"
        Effect    = "Allow"
        Principal = { AWS = [aws_iam_role.projector.arn] }
        Action    = ["sqs:SendMessage"]
        Resource  = aws_sqs_queue.dlq.arn
      },
      {
        Sid       = "DenyWorkloadConsume"
        Effect    = "Deny"
        Principal = { AWS = values(local.role_arns) }
        Action    = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource  = aws_sqs_queue.dlq.arn
      },
      {
        Sid    = "DenyNonProjectorSend"
        Effect = "Deny"
        Principal = { AWS = [
          aws_iam_role.ecs_execution.arn, aws_iam_role.ecs_task.arn, aws_iam_role.relay.arn,
          aws_iam_role.archiver.arn, aws_iam_role.scheduler.arn,
        ] }
        Action   = ["sqs:SendMessage"]
        Resource = aws_sqs_queue.dlq.arn
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# DynamoDB projection store
# ---------------------------------------------------------------------------

resource "aws_dynamodb_table" "projections" {
  name         = "${local.p}-settlement-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }
  attribute {
    name = "SK"
    type = "S"
  }
  attribute {
    name = "GSI1PK"
    type = "S"
  }
  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.key["projection"].arn
  }

  tags = local.tags
}

# ---------------------------------------------------------------------------
# S3 audit archive
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "audit" {
  bucket        = "${local.p}-ledger-audit-${local.account_id}"
  force_destroy = true
  tags          = local.tags
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.key["audit"].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket                  = aws_s3_bucket.audit.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "audit" {
  bucket = aws_s3_bucket.audit.id
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.p}-ledger-audit-policy"
    Statement = [
      {
        Sid       = "AllowArchiverObjectAppend"
        Effect    = "Allow"
        Principal = { AWS = [aws_iam_role.archiver.arn] }
        Action    = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"]
        Resource  = "${aws_s3_bucket.audit.arn}/ledger-audit/*"
      },
      {
        Sid       = "AllowArchiverBucketMetadata"
        Effect    = "Allow"
        Principal = { AWS = [aws_iam_role.archiver.arn] }
        Action    = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource  = aws_s3_bucket.audit.arn
      },
      {
        Sid       = "DenyWorkloadDeletes"
        Effect    = "Deny"
        Principal = { AWS = values(local.role_arns) }
        Action    = ["s3:DeleteObject", "s3:DeleteObjectVersion"]
        Resource  = [aws_s3_bucket.audit.arn, "${aws_s3_bucket.audit.arn}/*"]
      },
      {
        Sid    = "DenyNonArchiverWrites"
        Effect = "Deny"
        Principal = { AWS = [
          aws_iam_role.ecs_execution.arn, aws_iam_role.ecs_task.arn, aws_iam_role.projector.arn,
          aws_iam_role.relay.arn, aws_iam_role.scheduler.arn,
        ] }
        Action   = ["s3:PutObject"]
        Resource = [aws_s3_bucket.audit.arn, "${aws_s3_bucket.audit.arn}/*"]
      },
    ]
  })
  depends_on = [aws_s3_bucket_public_access_block.audit]
}

# ---------------------------------------------------------------------------
# RDS PostgreSQL
# ---------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name       = "${local.p}-db-subnets"
  subnet_ids = aws_subnet.private[*].id
  tags       = local.tags
}

resource "aws_db_instance" "main" {
  identifier              = "${local.p}-postgres"
  engine                  = "postgres"
  engine_version          = "16.3"
  instance_class          = "db.t4g.micro"
  allocated_storage       = 20
  storage_type            = "gp3"
  db_name                 = var.db_name
  username                = var.db_username
  password                = var.db_password
  port                    = 5432
  storage_encrypted       = true
  kms_key_id              = aws_kms_key.key["database"].arn
  publicly_accessible     = false
  skip_final_snapshot     = true
  deletion_protection     = false
  apply_immediately       = true
  backup_retention_period = 1
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.rds.id]
  tags                    = local.tags
}

# ---------------------------------------------------------------------------
# ElastiCache for Valkey
# ---------------------------------------------------------------------------

resource "aws_elasticache_subnet_group" "main" {
  name       = "${local.p}-cache-subnets"
  subnet_ids = aws_subnet.private[*].id
  tags       = local.tags
}

resource "aws_elasticache_replication_group" "cache" {
  replication_group_id       = "${local.p}-valkey"
  description                = "ClearLedger settlement projection cache"
  engine                     = "valkey"
  engine_version             = "8.0"
  node_type                  = "cache.t4g.micro"
  num_cache_clusters         = 1
  port                       = 6379
  subnet_group_name          = aws_elasticache_subnet_group.main.name
  security_group_ids         = [aws_security_group.valkey.id]
  transit_encryption_enabled = false
  at_rest_encryption_enabled = false
  automatic_failover_enabled = false
  apply_immediately          = true
  tags                       = local.tags
}

# ---------------------------------------------------------------------------
# Cognito
# ---------------------------------------------------------------------------

resource "aws_cognito_user_pool" "main" {
  name = "${local.p}-users"
  tags = local.tags
}

resource "aws_cognito_resource_server" "api" {
  user_pool_id = aws_cognito_user_pool.main.id
  identifier   = "clearledger"
  name         = "${local.p}-clearledger-api"

  scope {
    scope_name        = "read"
    scope_description = "Read settlement projections and ledgers"
  }
  scope {
    scope_name        = "write"
    scope_description = "Initiate settlements and append ledger entries"
  }
  scope {
    scope_name        = "admin"
    scope_description = "Administrative projection rebuilds"
  }
}

locals {
  cognito_clients = {
    read  = "clearledger/read"
    write = "clearledger/write"
    admin = "clearledger/admin"
  }
}

resource "aws_cognito_user_pool_client" "client" {
  for_each                             = local.cognito_clients
  name                                 = "${local.p}-${each.key}"
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["client_credentials"]
  allowed_oauth_scopes                 = [each.value]
  supported_identity_providers         = ["COGNITO"]
  explicit_auth_flows                  = ["ALLOW_REFRESH_TOKEN_AUTH"]
  depends_on                           = [aws_cognito_resource_server.api]
}

# ---------------------------------------------------------------------------
# Application Load Balancer
# ---------------------------------------------------------------------------

resource "aws_lb" "api" {
  name               = "${local.p}-alb"
  load_balancer_type = "application"
  internal           = false
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.alb.id]
  tags               = local.tags
}

resource "aws_lb_target_group" "api" {
  name                 = "${local.p}-api-tg"
  port                 = 8080
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 5

  health_check {
    enabled             = true
    path                = "/health/ready"
    protocol            = "HTTP"
    port                = "traffic-port"
    matcher             = "200"
    interval            = 5
    timeout             = 2
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = local.tags
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.api.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.api.arn
  }

  tags = local.tags
}

# ---------------------------------------------------------------------------
# ECS Fargate API service
# ---------------------------------------------------------------------------

resource "aws_ecs_cluster" "main" {
  name = "${local.p}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = local.tags
}

locals {
  api_environment = [
    { name = "PORT", value = "8080" },
    { name = "AWS_REGION", value = var.region },
    { name = "AWS_DEFAULT_REGION", value = var.region },
    { name = "AWS_ACCESS_KEY_ID", value = "test" },
    { name = "AWS_SECRET_ACCESS_KEY", value = "test" },
    { name = "AWS_ENDPOINT_URL", value = local.container_aws_endpoint },
    { name = "DATABASE_URL", value = local.database_url },
    { name = "SQS_QUEUE_URL", value = aws_sqs_queue.main.url },
    { name = "PROJECTION_TABLE", value = aws_dynamodb_table.projections.name },
    { name = "VALKEY_URL", value = local.valkey_url },
    { name = "CACHE_TTL_SECONDS", value = "90" },
    { name = "AUTH_ISSUER", value = local.issuer_url },
    { name = "AUTH_AUDIENCES", value = join(",", [for k in ["read", "write", "admin"] : aws_cognito_user_pool_client.client[k].id]) },
    { name = "AUTH_JWKS_URL", value = local.jwks_url },
    { name = "CLOUDWATCH_LOG_GROUP", value = aws_cloudwatch_log_group.lg["api"].name },
  ]
}

resource "aws_ecs_task_definition" "api" {
  family                   = "${local.p}-api"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name        = "api"
      image       = var.api_image
      essential   = true
      environment = local.api_environment
      portMappings = [
        { containerPort = 8080, hostPort = 8080, protocol = "tcp" }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.lg["api"].name
          awslogs-region        = var.region
          awslogs-stream-prefix = "api"
        }
      }
    }
  ])

  tags = local.tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_ecs_service" "api" {
  name                               = "${local.p}-api"
  cluster                            = aws_ecs_cluster.main.id
  task_definition                    = aws_ecs_task_definition.api.arn
  launch_type                        = "FARGATE"
  desired_count                      = 2
  deployment_minimum_healthy_percent = 100
  deployment_maximum_percent         = 200
  health_check_grace_period_seconds  = 30
  wait_for_steady_state              = false
  force_new_deployment               = false

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.api.arn
    container_name   = "api"
    container_port   = 8080
  }

  tags       = local.tags
  depends_on = [aws_lb_listener.http, aws_iam_role_policy.ecs_task, aws_iam_role_policy.ecs_execution]
}

# ---------------------------------------------------------------------------
# Lambda workers
# ---------------------------------------------------------------------------

resource "aws_lambda_function" "projector" {
  function_name = "${local.p}-projector"
  package_type  = "Image"
  image_uri     = var.projector_image
  role          = aws_iam_role.projector.arn
  timeout       = 3
  memory_size   = 256

  image_config {
    command     = []
    entry_point = []
  }

  environment {
    variables = {
      AWS_REGION            = var.region
      AWS_DEFAULT_REGION    = var.region
      AWS_ACCESS_KEY_ID     = "test"
      AWS_SECRET_ACCESS_KEY = "test"
      AWS_ENDPOINT_URL      = local.container_aws_endpoint
      PROJECTION_TABLE      = aws_dynamodb_table.projections.name
      VALKEY_URL            = local.valkey_url
      CLOUDWATCH_LOG_GROUP  = aws_cloudwatch_log_group.lg["projector"].name
    }
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.lg["projector"].name
  }

  tags       = local.tags
  depends_on = [aws_iam_role_policy.projector]
}

resource "aws_lambda_function" "relay" {
  function_name = "${local.p}-outbox-relay"
  package_type  = "Image"
  image_uri     = var.relay_image
  role          = aws_iam_role.relay.arn
  timeout       = 60
  memory_size   = 256

  image_config {
    command     = []
    entry_point = []
  }

  environment {
    variables = {
      AWS_REGION            = var.region
      AWS_DEFAULT_REGION    = var.region
      AWS_ACCESS_KEY_ID     = "test"
      AWS_SECRET_ACCESS_KEY = "test"
      AWS_ENDPOINT_URL      = local.container_aws_endpoint
      DATABASE_URL          = local.database_url
      SQS_QUEUE_URL         = aws_sqs_queue.main.url
      OUTBOX_BATCH_SIZE     = "50"
      CLOUDWATCH_LOG_GROUP  = aws_cloudwatch_log_group.lg["relay"].name
    }
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.lg["relay"].name
  }

  tags       = local.tags
  depends_on = [aws_iam_role_policy.relay]
}

resource "aws_lambda_function" "archiver" {
  function_name = "${local.p}-audit-archiver"
  package_type  = "Image"
  image_uri     = var.archiver_image
  role          = aws_iam_role.archiver.arn
  timeout       = 120
  memory_size   = 256

  image_config {
    command     = []
    entry_point = []
  }

  environment {
    variables = {
      AWS_REGION            = var.region
      AWS_DEFAULT_REGION    = var.region
      AWS_ACCESS_KEY_ID     = "test"
      AWS_SECRET_ACCESS_KEY = "test"
      AWS_ENDPOINT_URL      = local.container_aws_endpoint
      DATABASE_URL          = local.database_url
      AUDIT_BUCKET          = aws_s3_bucket.audit.bucket
      AUDIT_PREFIX          = "ledger-audit/"
      CLOUDWATCH_LOG_GROUP  = aws_cloudwatch_log_group.lg["archiver"].name
    }
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.lg["archiver"].name
  }

  tags       = local.tags
  depends_on = [aws_iam_role_policy.archiver]
}

resource "aws_lambda_event_source_mapping" "projector" {
  event_source_arn                   = aws_sqs_queue.main.arn
  function_name                      = aws_lambda_function.projector.arn
  enabled                            = true
  batch_size                         = 5
  maximum_batching_window_in_seconds = 0
  function_response_types            = ["ReportBatchItemFailures"]
  tags                               = local.tags
  depends_on                         = [aws_sqs_queue_policy.main, aws_iam_role_policy.projector]
}

# ---------------------------------------------------------------------------
# EventBridge Scheduler
# ---------------------------------------------------------------------------

resource "aws_scheduler_schedule" "outbox" {
  name                = "${local.p}-outbox-relay"
  group_name          = "default"
  state               = "ENABLED"
  schedule_expression = "rate(1 minute)"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.relay.arn
    role_arn = aws_iam_role.scheduler.arn
    input    = jsonencode({ source = "clearledger.scheduler", task = "outbox-relay" })
  }

  depends_on = [aws_iam_role_policy.scheduler]
}

resource "aws_scheduler_schedule" "archive" {
