CREATE SCHEMA IF NOT EXISTS clearledger;
CREATE TABLE clearledger.settlements (settlement_id UUID PRIMARY KEY, account_id TEXT NOT NULL, reference TEXT NOT NULL, debit_party TEXT NOT NULL, credit_party TEXT NOT NULL, current_status TEXT NOT NULL, current_stage TEXT NOT NULL, last_entry_id UUID, last_memo TEXT, version INTEGER NOT NULL, entry_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE clearledger.events (seq BIGSERIAL PRIMARY KEY, event_id UUID NOT NULL UNIQUE, settlement_id UUID NOT NULL REFERENCES clearledger.settlements(settlement_id) ON DELETE CASCADE, aggregate_version INTEGER NOT NULL, event_type TEXT NOT NULL, correlation_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (settlement_id, aggregate_version), UNIQUE (settlement_id, idempotency_key));
CREATE TABLE clearledger.outbox (seq BIGSERIAL PRIMARY KEY, event_id UUID NOT NULL UNIQUE REFERENCES clearledger.events(event_id) ON DELETE CASCADE, settlement_id UUID NOT NULL REFERENCES clearledger.settlements(settlement_id) ON DELETE CASCADE, aggregate_version INTEGER NOT NULL, correlation_id TEXT NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), published_at TIMESTAMPTZ, archived_at TIMESTAMPTZ, attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT);
CREATE TABLE clearledger.idempotency_keys (scope TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, status_code INTEGER NOT NULL, response_body JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (scope, idempotency_key));
CREATE TABLE clearledger.debug_log (id serial, tbl text, op text, newrow jsonb, at timestamptz default clock_timestamp());
CREATE FUNCTION clearledger.dbg() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO clearledger.debug_log(tbl,op,newrow) VALUES (TG_TABLE_NAME, TG_OP, to_jsonb(NEW)); IF NEW.last_memo IS NULL AND TG_TABLE_NAME='settlements' THEN NEW.last_memo := OLD.last_memo; END IF; RETURN NEW; END $$;
CREATE TRIGGER t_dbg BEFORE INSERT OR UPDATE ON clearledger.settlements FOR EACH ROW EXECUTE FUNCTION clearledger.dbg();
CREATE FUNCTION clearledger.dbg2() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO clearledger.debug_log(tbl,op,newrow) VALUES (TG_TABLE_NAME, TG_OP, to_jsonb(NEW)); RETURN NEW; END $$;
CREATE TRIGGER t_dbg BEFORE INSERT OR UPDATE ON clearledger.events FOR EACH ROW EXECUTE FUNCTION clearledger.dbg2();
CREATE TRIGGER t_dbg BEFORE INSERT OR UPDATE ON clearledger.outbox FOR EACH ROW EXECUTE FUNCTION clearledger.dbg2();
CREATE TRIGGER t_dbg BEFORE INSERT OR UPDATE ON clearledger.idempotency_keys FOR EACH ROW EXECUTE FUNCTION clearledger.dbg2();
CREATE INDEX idx_clearledger_outbox_unpublished ON clearledger.outbox (seq) WHERE published_at IS NULL;
CREATE INDEX idx_clearledger_outbox_unarchived ON clearledger.outbox (seq) WHERE published_at IS NOT NULL AND archived_at IS NULL;
CREATE INDEX idx_clearledger_events_settlement_version ON clearledger.events (settlement_id, aggregate_version);
CREATE UNIQUE INDEX idx_clearledger_idempotency_event ON clearledger.idempotency_keys (((response_body->>'eventId')::uuid));
CREATE UNIQUE INDEX idx_clearledger_idempotency_version ON clearledger.idempotency_keys (((response_body->>'settlementId')::uuid), ((response_body->>'version')::integer));
CREATE UNIQUE INDEX idx_clearledger_entry_id ON clearledger.events (settlement_id, ((payload->'data'->>'entryId')::uuid)) WHERE event_type = 'LedgerEntryRecorded';
EOF
